ALTER TABLE accounts ADD COLUMN phone_verified_at TIMESTAMPTZ;
CREATE INDEX swipe_events_actor_recent ON swipe_events(actor_id,occurred_at DESC,id DESC);
CREATE INDEX swipe_events_target_segment ON swipe_events(target_id,segment_key,occurred_at);
CREATE TABLE score_rebuild_runs(id BIGSERIAL PRIMARY KEY,completed_at TIMESTAMPTZ NOT NULL,policy_version TEXT NOT NULL);
ALTER TABLE score_rebuild_runs ENABLE ROW LEVEL SECURITY;
CREATE TABLE score_projection_receipts(event_id BIGINT PRIMARY KEY REFERENCES swipe_events(id),projected_at TIMESTAMPTZ NOT NULL,policy_version TEXT NOT NULL);
CREATE TABLE score_actor_weights(actor_id UUID PRIMARY KEY REFERENCES accounts(user_id),weight DOUBLE PRECISION NOT NULL CHECK(weight IN(0,0.25,1)),computed_at TIMESTAMPTZ NOT NULL,policy_version TEXT NOT NULL);
CREATE TABLE score_segment_priors(segment_key TEXT PRIMARY KEY,mean DOUBLE PRECISION NOT NULL CHECK(mean>0 AND mean<1),support DOUBLE PRECISION NOT NULL CHECK(support>=0),policy_version TEXT NOT NULL,computed_at TIMESTAMPTZ NOT NULL);
CREATE TABLE score_values(candidate_id UUID NOT NULL REFERENCES accounts(user_id),segment_key TEXT NOT NULL,likes_w DOUBLE PRECISION NOT NULL CHECK(likes_w>=0),passes_w DOUBLE PRECISION NOT NULL CHECK(passes_w>=0),prior_mean DOUBLE PRECISION NOT NULL CHECK(prior_mean>0 AND prior_mean<1),theta_mean DOUBLE PRECISION NOT NULL CHECK(theta_mean BETWEEN 0 AND 1),percentile DOUBLE PRECISION NOT NULL CHECK(percentile BETWEEN 0 AND 1),policy_version TEXT NOT NULL,computed_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(candidate_id,segment_key));
CREATE TABLE score_reply_windows(match_id UUID PRIMARY KEY REFERENCES matches(id),opener_sender_id UUID NOT NULL REFERENCES accounts(user_id),respondent_id UUID NOT NULL REFERENCES accounts(user_id),opened_at TIMESTAMPTZ NOT NULL,first_reply_at TIMESTAMPTZ,CHECK(opener_sender_id<>respondent_id),CHECK(first_reply_at IS NULL OR first_reply_at>=opened_at));
CREATE TABLE score_reply_stats(user_id UUID PRIMARY KEY REFERENCES accounts(user_id),opportunities BIGINT NOT NULL CHECK(opportunities>=0),replies BIGINT NOT NULL CHECK(replies>=0 AND replies<=opportunities),computed_at TIMESTAMPTZ NOT NULL);
CREATE OR REPLACE VIEW discovery_quality AS SELECT s.candidate_id,s.segment_key,s.likes_w,s.passes_w,s.percentile,(COALESCE(r.replies,0)+3.0)/(COALESCE(r.opportunities,0)+4.0)::double precision AS reply_rate,s.prior_mean,COALESCE(r.opportunities,0)::bigint AS completed_matches FROM score_values s LEFT JOIN score_reply_stats r ON r.user_id=s.candidate_id;
ALTER TABLE score_projection_receipts ENABLE ROW LEVEL SECURITY;
ALTER TABLE score_actor_weights ENABLE ROW LEVEL SECURITY;
ALTER TABLE score_segment_priors ENABLE ROW LEVEL SECURITY;
ALTER TABLE score_values ENABLE ROW LEVEL SECURITY;
ALTER TABLE score_reply_windows ENABLE ROW LEVEL SECURITY;
ALTER TABLE score_reply_stats ENABLE ROW LEVEL SECURITY;
CREATE TRIGGER immutable_score_receipt BEFORE UPDATE OR DELETE ON score_projection_receipts FOR EACH ROW EXECUTE FUNCTION immutable_swipe_event();
